const ppm = parseFloat(msg.payload);
let color, label, textColor;
if (ppm <= 800)       { color = '#00c853'; label = 'Good';          textColor = '#ffffff'; }
else if (ppm <= 1200) { color = '#ffd600'; label = 'Moderate';      textColor = '#000000'; }
else if (ppm <= 1600) { color = '#ff6d00'; label = 'Poor';          textColor = '#ffffff'; }
else                  { color = '#d50000'; label = 'Very poor'; textColor = '#ffffff'; }
msg.payload = { ppm, color, label, textColor };
return msg;

function getColor(value, type) {
    if (type === 'temp') {
        if (value < 5)  return { color: '#2196F3', label: 'Cold' };
        if (value < 10) return { color: '#00e5ff', label: 'Cool' };
        if (value < 20) return { color: '#00c853', label: 'Mild' };
        if (value < 30) return { color: '#ffd600', label: 'Warm' };
        return { color: '#d50000', label: 'Hot' };
    } else if (type === 'hum') {
        if (value >= 40 && value <= 60) return { color: '#00e5ff', label: 'Very good' };
        if (value >= 30 && value <= 70) return { color: '#00c853', label: 'Good' };
        if (value >= 20 && value <= 80) return { color: '#ffd600', label: 'Moderate' };
        if (value >= 10 && value <= 90) return { color: '#ff6d00', label: 'Poor' };
        return { color: '#d50000', label: 'Very poor' };
    } else if (type === 'pres') {
        if (value >= 1013 && value <= 1023) return { color: '#00e5ff', label: 'Very good' };
        if (value >= 1003 && value <= 1033) return { color: '#00c853', label: 'Good' };
        if (value >= 993  && value <= 1043) return { color: '#ffd600', label: 'Moderate' };
        if (value >= 983  && value <= 1053) return { color: '#ff6d00', label: 'Poor' };
        return { color: '#d50000', label: 'Very poor' };
    }
}

